    """Restore the 3-marked cells by 180-degree rotational symmetry."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                partner = grid[h - 1 - r][w - 1 - c]
                # When both symmetric positions are marked, the demo's repeated
                # pattern establishes their underlying value as 6.
                out[r][c] = 6 if partner == 3 else partner
